//! Identities from PEM, DER, files, PKCS #12 and encrypted keys, all generated by the test.

mod support;

use std::fs;

use coqui_sslcontext::{Error, Identity, KeyPassword, KeyType, Secret};
use rustls::pki_types::pem::PemObject;
use support::pki::{Ca, Leaf};

fn pem(label: &str, der: &[u8]) -> String {
    let body = pem_body(der);
    format!("-----BEGIN {label}-----\n{body}-----END {label}-----\n")
}

fn pem_body(der: &[u8]) -> String {
    use std::fmt::Write;
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut text = String::new();
    for chunk in der.chunks(3) {
        let block = u32::from(chunk[0]) << 16
            | u32::from(*chunk.get(1).unwrap_or(&0)) << 8
            | u32::from(*chunk.get(2).unwrap_or(&0));
        for index in 0..4 {
            if index <= chunk.len() {
                text.push(char::from(
                    ALPHABET[(block >> (18 - 6 * index) & 63) as usize],
                ));
            } else {
                text.push('=');
            }
        }
    }
    let mut wrapped = String::new();
    for line in text.as_bytes().chunks(64) {
        writeln!(wrapped, "{}", std::str::from_utf8(line).unwrap()).unwrap();
    }
    wrapped
}

fn client() -> Leaf {
    Ca::new("Identity CA").issue_client("identity-user")
}

fn chain_pem(leaf: &Leaf) -> String {
    leaf.chain
        .iter()
        .map(|der| pem("CERTIFICATE", der.as_ref()))
        .collect()
}

#[test]
fn an_identity_comes_from_der_pem_or_files_alike() {
    let leaf = client();
    let key_pem = pem("PRIVATE KEY", &leaf.key_pkcs8);

    let from_der = Identity::from_der(&leaf.chain, &leaf.key_pkcs8).unwrap();
    let from_pem = Identity::from_pem(chain_pem(&leaf).as_bytes(), key_pem.as_bytes()).unwrap();
    assert_eq!(from_der.info().fingerprint(), from_pem.info().fingerprint());
    assert_eq!(from_der.chain().len(), leaf.chain.len());

    let directory = tempfile::tempdir().unwrap();
    let path = |name: &str| directory.path().join(name);
    fs::write(path("cert.pem"), chain_pem(&leaf)).unwrap();
    fs::write(path("key.pem"), &key_pem).unwrap();
    fs::write(path("cert.der"), leaf.leaf_der()).unwrap();
    fs::write(path("key.der"), &leaf.key_pkcs8).unwrap();
    fs::write(path("both.pem"), format!("{}{key_pem}", chain_pem(&leaf))).unwrap();

    for (certificate, key) in [
        ("cert.pem", "key.pem"),
        ("cert.pem", "key.der"),
        ("cert.der", "key.pem"),
        ("cert.der", "key.der"),
    ] {
        let identity = Identity::load(path(certificate), path(key), KeyPassword::None).unwrap();
        assert_eq!(identity.info().fingerprint(), from_der.info().fingerprint());
    }
    let combined = Identity::load_combined(path("both.pem"), KeyPassword::None).unwrap();
    assert_eq!(combined.info().fingerprint(), from_der.info().fingerprint());
}

#[test]
fn missing_or_mismatched_material_is_a_credential_error() {
    let leaf = client();
    assert!(matches!(
        Identity::from_pem(b"nothing", pem("PRIVATE KEY", &leaf.key_pkcs8).as_bytes()),
        Err(Error::Credential(_)) | Err(Error::Tls(_))
    ));
    assert!(matches!(
        Identity::from_der(&leaf.chain, b"\x00"),
        Err(Error::Credential(_))
    ));
    assert!(matches!(
        Identity::load("no-such-file.pem", "no-such-key.pem", KeyPassword::None),
        Err(Error::Io(_))
    ));
    let error = Identity::from_der(&leaf.chain, b"\x00")
        .unwrap_err()
        .to_string();
    assert!(!error.contains("0x00"), "{error}");
}

#[test]
fn a_certificate_says_its_serial_digests_validity_and_key_size() {
    let leaf = client();
    let identity = Identity::from_der(&leaf.chain, &leaf.key_pkcs8).unwrap();
    let info = identity.info();
    assert_eq!(info.key_type(), KeyType::EcP256);
    assert_eq!(info.key_bits(), 256);
    assert!(info.valid_now());
    assert!(info.not_before() < info.not_after());
    assert!(!info.serial().is_empty());
    assert_eq!(info.sha256(), info.fingerprint());
    assert_ne!(info.sha1(), &[0; 20]);
    assert!(PemCheck::roundtrips(&leaf));
}

struct PemCheck;
impl PemCheck {
    fn roundtrips(leaf: &Leaf) -> bool {
        let text = chain_pem(leaf);
        rustls::pki_types::CertificateDer::pem_slice_iter(text.as_bytes()).count()
            == leaf.chain.len()
    }
}

#[test]
fn a_password_comes_from_a_value_a_file_or_a_callback_and_never_prints() {
    let directory = tempfile::tempdir().unwrap();
    let file = directory.path().join("password");
    fs::write(&file, "from-file\r\nsecond line\n").unwrap();
    let secret =
        |password: &KeyPassword| password.resolve().unwrap().map(|s| s.expose().to_owned());
    assert_eq!(secret(&KeyPassword::None), None);
    assert_eq!(
        secret(&KeyPassword::from("value")).as_deref(),
        Some("value")
    );
    assert_eq!(
        secret(&KeyPassword::File(file)).as_deref(),
        Some("from-file")
    );
    let called = KeyPassword::callback(|| Some(Secret::new("asked")));
    assert_eq!(secret(&called).as_deref(), Some("asked"));
    assert_eq!(secret(&KeyPassword::callback(|| None)), None);
    assert!(!format!("{:?}", KeyPassword::from("hunter2")).contains("hunter2"));
    assert!(
        KeyPassword::File("missing-password-file".into())
            .resolve()
            .is_err()
    );
}

#[cfg(feature = "encrypted-keys")]
mod encrypted {
    use super::*;

    fn encrypted_pem(leaf: &Leaf, password: &str) -> String {
        use pkcs8::der::Decode;
        let info = pkcs8::PrivateKeyInfoRef::from_der(&leaf.key_pkcs8).unwrap();
        let document = info.encrypt(password).unwrap();
        document
            .to_pem("ENCRYPTED PRIVATE KEY", pkcs8::der::pem::LineEnding::LF)
            .unwrap()
            .to_string()
    }

    #[test]
    fn an_encrypted_key_opens_with_its_password_from_any_source() {
        let leaf = client();
        let key = encrypted_pem(&leaf, "s3cret");
        let certificates = chain_pem(&leaf);
        for password in [
            KeyPassword::from("s3cret"),
            KeyPassword::callback(|| Some(Secret::new("s3cret"))),
        ] {
            let identity =
                Identity::from_pem_with(certificates.as_bytes(), key.as_bytes(), &password)
                    .unwrap();
            assert_eq!(identity.info().subject(), "CN=identity-user");
        }
        let directory = tempfile::tempdir().unwrap();
        let file = directory.path().join("password");
        fs::write(&file, "s3cret\n").unwrap();
        let identity = Identity::from_pem_with(
            certificates.as_bytes(),
            key.as_bytes(),
            &KeyPassword::File(file),
        )
        .unwrap();
        assert_eq!(identity.chain().len(), leaf.chain.len());
    }

    #[test]
    fn a_missing_or_wrong_password_is_an_error_that_does_not_quote_it() {
        let leaf = client();
        let key = encrypted_pem(&leaf, "s3cret");
        let certificates = chain_pem(&leaf);
        for (password, said) in [
            (KeyPassword::None, "no password was given"),
            (KeyPassword::from("wrong-guess"), "does not decrypt"),
        ] {
            let error = Identity::from_pem_with(certificates.as_bytes(), key.as_bytes(), &password)
                .unwrap_err();
            assert!(matches!(error, Error::Credential(_)), "{error}");
            assert!(error.to_string().contains(said), "{error}");
            assert!(!error.to_string().contains("wrong-guess"));
        }
    }
}

#[cfg(not(feature = "encrypted-keys"))]
#[test]
fn an_encrypted_key_without_the_feature_is_unsupported() {
    let leaf = client();
    let key = "-----BEGIN ENCRYPTED PRIVATE KEY-----\nAAAA\n-----END ENCRYPTED PRIVATE KEY-----\n";
    let error = Identity::from_pem_with(
        chain_pem(&leaf).as_bytes(),
        key.as_bytes(),
        &KeyPassword::None,
    )
    .unwrap_err();
    assert!(matches!(error, Error::Unsupported(_)), "{error}");
}

#[cfg(feature = "pkcs12")]
mod pkcs12 {
    use super::*;
    use p12_keystore::{Certificate, KeyStore, KeyStoreEntry, PrivateKey, PrivateKeyChain};

    fn archive(leaf: &Leaf, password: &str) -> Vec<u8> {
        let certificates = leaf
            .chain
            .iter()
            .map(|der| Certificate::from_der(der.as_ref()).unwrap());
        let chain = PrivateKeyChain::new(
            vec![1_u8, 2, 3, 4],
            PrivateKey::from_der(&leaf.key_pkcs8).unwrap(),
            certificates,
        );
        let mut store = KeyStore::new();
        store.add_entry("client", KeyStoreEntry::PrivateKeyChain(chain));
        store.writer(password).write().unwrap()
    }

    #[test]
    fn a_pkcs12_file_gives_its_key_and_chain() {
        let leaf = client();
        let data = archive(&leaf, "p12-pass");
        let identity = Identity::from_pkcs12(&data, &KeyPassword::from("p12-pass")).unwrap();
        assert_eq!(identity.info().subject(), "CN=identity-user");
        assert_eq!(identity.chain().len(), leaf.chain.len());

        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("client.p12");
        fs::write(&path, &data).unwrap();
        let loaded = Identity::load_combined(&path, KeyPassword::from("p12-pass")).unwrap();
        assert_eq!(loaded.info().fingerprint(), identity.info().fingerprint());
    }

    #[test]
    fn a_wrong_pkcs12_password_is_a_credential_error() {
        let data = archive(&client(), "p12-pass");
        let error = Identity::from_pkcs12(&data, &KeyPassword::from("nope")).unwrap_err();
        assert!(matches!(error, Error::Credential(_)), "{error}");
        assert!(!error.to_string().contains("nope"));
        assert!(Identity::from_pkcs12(b"not pkcs12", &KeyPassword::None).is_err());
    }
}
